    axi_int_ar_ready = 1'd0;
    if ((socbushandler_rr_read_grant == 1'd0)) begin
        axi_int_ar_ready = socbushandler_ar_ready;
    end
end
always @(*) begin
    axi_int_r_valid = 1'd0;
    if ((socbushandler_rr_read_grant == 1'd0)) begin
        axi_int_r_valid = socbushandler_r_valid;
    end
end
assign axi_int_r_payload_resp = socbushandler_r_payload_resp;
assign axi_int_r_payload_data = socbushandler_r_payload_data;
always @(*) begin
    axi_int_aw_ready = 1'd0;
    if ((socbushandler_rr_write_grant == 1'd0)) begin
        axi_int_aw_ready = socbushandler_aw_ready;
    end
end
always @(*) begin
    axi_int_w_ready = 1'd0;
    if ((socbushandler_rr_write_grant == 1'd0)) begin
        axi_int_w_ready = socbushandler_w_ready;
    end
end
always @(*) begin
    axi_int_b_valid = 1'd0;
    if ((socbushandler_rr_write_grant == 1'd0)) begin
        axi_int_b_valid = socbushandler_b_valid;
    end
end
assign axi_int_b_payload_resp = socbushandler_b_payload_resp;
assign socbushandler_rr_write_ce = ((~((socbushandler_aw_valid | socbushandler_w_valid) | socbushandler_b_valid)) & socbushandler_wr_lock_empty);
assign socbushandler_rr_read_ce = ((~(socbushandler_ar_valid | socbushandler_r_valid)) & socbushandler_rd_lock_empty);
assign socbushandler_rr_write_request = {((axi_int_aw_valid | axi_int_w_valid) | axi_int_b_valid)};
assign socbushandler_rr_read_request = {(axi_int_ar_valid | axi_int_r_valid)};
assign socbushandler_rr_write_grant = 1'd0;
assign socbushandler_rr_read_grant = 1'd0;
assign socbushandler_wr_lock_full = (socbushandler_wr_lock_counter == 8'hff);
assign socbushandler_wr_lock_empty = (socbushandler_wr_lock_counter == 1'd0);
assign socbushandler_wr_lock_stall = ((socbushandler_aw_valid & socbushandler_aw_ready) & socbushandler_wr_lock_full);
assign socbushandler_rd_lock_full = (socbushandler_rd_lock_counter == 8'hff);
assign socbushandler_rd_lock_empty = (socbushandler_rd_lock_counter == 1'd0);
assign socbushandler_rd_lock_stall = ((socbushandler_ar_valid & socbushandler_ar_ready) & socbushandler_rd_lock_full);
assign socbushandler_axilitedecoder_slave_sel_dec0 = (socbushandler_aw_payload_addr[31:16] == 1'd0);
assign socbushandler_axilitedecoder_slave_sel_dec1 = (socbushandler_ar_payload_addr[31:16] == 1'd0);
always @(*) begin
    socbushandler_axilitedecoder_slave_sel0 = 1'd0;
    if (socbushandler_axilitedecoder_axiliterequestcounter0_empty) begin
        socbushandler_axilitedecoder_slave_sel0 = socbushandler_axilitedecoder_slave_sel_dec0;
    end else begin
        socbushandler_axilitedecoder_slave_sel0 = socbushandler_axilitedecoder_slave_sel_reg0;
    end
end
always @(*) begin
    socbushandler_axilitedecoder_slave_sel1 = 1'd0;
    if (socbushandler_axilitedecoder_axiliterequestcounter1_empty) begin
        socbushandler_axilitedecoder_slave_sel1 = socbushandler_axilitedecoder_slave_sel_dec1;
    end else begin
        socbushandler_axilitedecoder_slave_sel1 = socbushandler_axilitedecoder_slave_sel_reg1;
    end
end
assign socbushandler_axilitedecoder0 = (socbushandler_axilitedecoder_axiliterequestcounter0_empty | (socbushandler_axilitedecoder_slave_sel_dec0 == socbushandler_axilitedecoder_slave_sel_reg0));
assign socbushandler_axilitedecoder1 = (socbushandler_axilitedecoder_axiliterequestcounter1_empty | (socbushandler_axilitedecoder_slave_sel_dec1 == socbushandler_axilitedecoder_slave_sel_reg1));
assign uiboardhardaxi_ar_valid = ((socbushandler_ar_valid & socbushandler_axilitedecoder_slave_sel1) & socbushandler_axilitedecoder1);
assign uiboardhardaxi_ar_payload_addr = socbushandler_ar_payload_addr;
assign uiboardhardaxi_ar_payload_prot = socbushandler_ar_payload_prot;
assign uiboardhardaxi_r_ready = (socbushandler_r_ready & socbushandler_axilitedecoder_slave_sel1);
assign uiboardhardaxi_aw_valid = ((socbushandler_aw_valid & socbushandler_axilitedecoder_slave_sel0) & socbushandler_axilitedecoder0);
assign uiboardhardaxi_aw_payload_addr = socbushandler_aw_payload_addr;
assign uiboardhardaxi_aw_payload_prot = socbushandler_aw_payload_prot;
assign uiboardhardaxi_w_valid = (socbushandler_w_valid & socbushandler_axilitedecoder_slave_sel0);
assign uiboardhardaxi_w_payload_data = socbushandler_w_payload_data;
assign uiboardhardaxi_w_payload_strb = socbushandler_w_payload_strb;
assign uiboardhardaxi_b_ready = (socbushandler_b_ready & socbushandler_axilitedecoder_slave_sel0);
assign socbushandler_axilitedecoder_axiliterequestcounter0_full = (socbushandler_axilitedecoder_axiliterequestcounter0_counter == 8'hff);
assign socbushandler_axilitedecoder_axiliterequestcounter0_empty = (socbushandler_axilitedecoder_axiliterequestcounter0_counter == 1'd0);
assign socbushandler_axilitedecoder_axiliterequestcounter0_stall = ((socbushandler_aw_valid & socbushandler_aw_ready) & socbushandler_axilitedecoder_axiliterequestcounter0_full);
assign socbushandler_axilitedecoder_axiliterequestcounter1_full = (socbushandler_axilitedecoder_axiliterequestcounter1_counter == 8'hff);
assign socbushandler_axilitedecoder_axiliterequestcounter1_empty = (socbushandler_axilitedecoder_axiliterequestcounter1_counter == 1'd0);
assign socbushandler_axilitedecoder_axiliterequestcounter1_stall = ((socbushandler_ar_valid & socbushandler_ar_ready) & socbushandler_axilitedecoder_axiliterequestcounter1_full);
assign socbushandler_error = (socbushandler_wr_error | socbushandler_rd_error);
assign socbushandler_wr_timer_done = (socbushandler_wr_timer_count == 1'd0);
assign socbushandler_rd_timer_done = (socbushandler_rd_timer_count == 1'd0);
always @(*) begin
    socbushandler_aw_ready = 1'd0;
    socbushandler_b_payload_resp = 2'd0;
    socbushandler_b_valid = 1'd0;
    socbushandler_fsm0_next_state = 1'd0;
    socbushandler_w_ready = 1'd0;
    socbushandler_wr_error = 1'd0;
    socbushandler_wr_timer_wait = 1'd0;
    socbushandler_aw_ready = (uiboardhardaxi_aw_ready & ({1{socbushandler_axilitedecoder_slave_sel0}} & {1{socbushandler_axilitedecoder0}}));
    case (socbushandler_fsm0_state)
        1'd1: begin
            socbushandler_aw_ready = socbushandler_aw_valid;
        end
        default: begin
        end
    endcase
    socbushandler_b_payload_resp = (uiboardhardaxi_b_payload_resp & {2{socbushandler_axilitedecoder_slave_sel0}});
    case (socbushandler_fsm0_state)
        1'd1: begin
            socbushandler_b_payload_resp = 2'd2;
        end
        default: begin
        end
    endcase
    socbushandler_b_valid = (uiboardhardaxi_b_valid & {1{socbushandler_axilitedecoder_slave_sel0}});
    case (socbushandler_fsm0_state)
        1'd1: begin
            socbushandler_b_valid = ((~socbushandler_aw_valid) & (~socbushandler_w_valid));
        end
        default: begin
        end
    endcase
    socbushandler_w_ready = (uiboardhardaxi_w_ready & {1{socbushandler_axilitedecoder_slave_sel0}});
    case (socbushandler_fsm0_state)
        1'd1: begin
            socbushandler_w_ready = socbushandler_w_valid;
        end
        default: begin
        end
    endcase
    case (socbushandler_fsm0_state)
        1'd1: begin
        end
        default: begin
            socbushandler_wr_timer_wait = ((socbushandler_aw_valid & (~socbushandler_aw_ready)) | (socbushandler_w_valid & (~socbushandler_w_ready)));
        end
    endcase
    socbushandler_fsm0_next_state = socbushandler_fsm0_state;
    case (socbushandler_fsm0_state)
        1'd1: begin
            if ((socbushandler_b_valid & socbushandler_b_ready)) begin
                socbushandler_fsm0_next_state = 1'd0;
            end
        end
        default: begin
            if ((socbushandler_wr_timer_done & socbushandler_wr_timer_wait)) begin
                socbushandler_fsm0_next_state = 1'd1;
            end
        end
    endcase
    case (socbushandler_fsm0_state)
        1'd1: begin
        end
        default: begin
            if ((socbushandler_wr_timer_done & socbushandler_wr_timer_wait)) begin
                socbushandler_wr_error = 1'd1;
            end
        end
    endcase
